# /// script
# [tool.databricks.environment]
# environment_version = "5"
# ///
# MAGIC %md
# MAGIC # Cost Observability — Gold Table Share Publisher
# MAGIC
# MAGIC Run this notebook with **Run All** in a workspace that can read `system.*`
# MAGIC through a SQL warehouse. It builds v2 gold tables in Unity Catalog from those
# MAGIC system tables, publishes the warehouse gold through a Delta Share, and
# MAGIC optionally grants an existing recipient access to that share.
# MAGIC
# MAGIC **What this publishes**
# MAGIC - Warehouse gold (`daily_*` and related aggregates) built from `system.*`
# MAGIC - Optional Unity Gateway gold when its administrator-managed source is configured
# MAGIC - Connected cloud invoice actuals are intentionally out of scope
# MAGIC
# MAGIC **What this does not publish**
# MAGIC - Lakebase / Postgres copies. Those are the local app serving path in the
# MAGIC   app workspace. Recipients do **not** receive Lakebase over Delta Sharing.
# MAGIC
# MAGIC **Sharing mode** (`share_mode` widget)
# MAGIC - `table` (default, upgrade-safe): shares the individual gold tables built in
# MAGIC   this run without replacing an existing table-level share.
# MAGIC - `schema` (recommended for new shares): shares the whole target schema, so every
# MAGIC   current **and future** gold table flows to recipients without re-running the
# MAGIC   share step. Converting an existing table-level share requires an explicit
# MAGIC   `allow_schema_migration=yes` confirmation because recipient access must be
# MAGIC   checked first.
# MAGIC
# MAGIC **Required privileges**
# MAGIC - Read the referenced `system.*` tables
# MAGIC - `USE CATALOG` and `CREATE SCHEMA` on the target catalog
# MAGIC - `CREATE SHARE` on the metastore and ownership of the resulting share
# MAGIC - `SELECT` on every generated gold table
# MAGIC
# MAGIC The notebook is idempotent. Re-running replaces available gold data,
# MAGIC converges the share to the requested mode without duplicate-object errors,
# MAGIC skips permission-dependent or unconfigured optional tables, and fails loudly
# MAGIC on required-table errors.
# MAGIC
# MAGIC Contract: `b369c4e61400b68143fd4b02fc04937e1c0af132fa3a9364774cf13bd924fbe0`

# COMMAND ----------

import json
import re
from typing import Any

spark: Any = globals().get("spark")
display: Any = globals().get("display")


def _widget(name: str, default: str, label: str) -> None:
    try:
        dbutils.widgets.get(name)  # noqa: F821
    except Exception:
        dbutils.widgets.text(name, default, label)  # noqa: F821


def _dropdown(name: str, default: str, choices: list, label: str) -> None:
    try:
        dbutils.widgets.get(name)  # noqa: F821
    except Exception:
        dbutils.widgets.dropdown(name, default, choices, label)  # noqa: F821


_widget("target_catalog", "main", "Target catalog")
_widget("target_schema", "cost_obs_shared", "Target schema")
_widget("share_name", "cost_obs_share", "Delta Share name")
_dropdown("share_mode", "table", ["table", "schema"], "Share mode")
_dropdown("allow_schema_migration", "no", ["no", "yes"], "Replace existing table share")
_widget("recipient_name", "", "Existing recipient name (optional)")
_widget("lookback_days", "180", "Billing/query lookback days")
_widget("ai_gateway_table", "", "Unity Gateway usage table FQN (optional)")

CATALOG = dbutils.widgets.get("target_catalog").strip()  # noqa: F821
SCHEMA = dbutils.widgets.get("target_schema").strip()  # noqa: F821
SHARE = dbutils.widgets.get("share_name").strip()  # noqa: F821
SHARE_MODE = dbutils.widgets.get("share_mode").strip().lower()  # noqa: F821
ALLOW_SCHEMA_MIGRATION = dbutils.widgets.get("allow_schema_migration").strip().lower()  # noqa: F821
RECIPIENT = dbutils.widgets.get("recipient_name").strip()  # noqa: F821
LOOKBACK_DAYS = int(dbutils.widgets.get("lookback_days"))  # noqa: F821
AI_GATEWAY_TABLE = dbutils.widgets.get("ai_gateway_table").strip()  # noqa: F821

_IDENTIFIER = re.compile(r"^[A-Za-z_][A-Za-z0-9_-]*$")
_FQN = re.compile(r"^[A-Za-z_][A-Za-z0-9_-]*(\.[A-Za-z_][A-Za-z0-9_-]*){0,2}$")
for field, value in {
    "target_catalog": CATALOG,
    "target_schema": SCHEMA,
    "share_name": SHARE,
}.items():
    if not _IDENTIFIER.fullmatch(value):
        raise ValueError(f"{field} must be a single catalog identifier: {value!r}")
if RECIPIENT and not _IDENTIFIER.fullmatch(RECIPIENT):
    raise ValueError("recipient_name must be a single recipient identifier")
if AI_GATEWAY_TABLE and not _FQN.fullmatch(AI_GATEWAY_TABLE.replace("`", "")):
    raise ValueError("ai_gateway_table must be a table name or catalog.schema.table")
if SHARE_MODE not in ("schema", "table"):
    raise ValueError("share_mode must be 'schema' or 'table'")
if ALLOW_SCHEMA_MIGRATION not in ("yes", "no"):
    raise ValueError("allow_schema_migration must be 'yes' or 'no'")
if not 30 <= LOOKBACK_DAYS <= 730:
    raise ValueError("lookback_days must be between 30 and 730")

print(f"Publishing warehouse gold to {CATALOG}.{SCHEMA}")
print(f"Delta Share: {SHARE}  (mode: {SHARE_MODE})")
print(f"Recipient: {RECIPIENT or 'not granted by this run'}")
print("Lakebase is not part of this share. Receiving apps import shared gold into Lakebase.")

# COMMAND ----------

SOURCE_TABLES = json.loads('["system.access.workspaces_latest","system.billing.list_prices","system.billing.usage","system.compute.clusters","system.compute.warehouse_events","system.compute.warehouses","system.dashboards.dashboards","system.lakeflow.job_run_timeline","system.lakeflow.pipelines","system.query.history","system.serving.served_entities"]')
TABLE_DEPENDENCIES = json.loads('{"daily_usage_summary":["system.billing.list_prices","system.billing.usage"],"daily_product_breakdown":["system.billing.list_prices","system.billing.usage"],"daily_workspace_breakdown":["system.access.workspaces_latest","system.billing.list_prices","system.billing.usage"],"sql_tool_attribution":["system.billing.list_prices","system.billing.usage","system.query.history"],"daily_query_stats":["system.query.history"],"dbsql_cost_per_query":["system.billing.list_prices","system.billing.usage","system.query.history"],"daily_tag_summary":["system.billing.list_prices","system.billing.usage"],"daily_apps_summary":["system.billing.list_prices","system.billing.usage"],"daily_sku_breakdown":["system.billing.list_prices","system.billing.usage"],"daily_job_pipeline_spend":["system.billing.list_prices","system.billing.usage","system.lakeflow.pipelines"],"daily_interactive_spend":["system.billing.list_prices","system.billing.usage","system.compute.clusters"],"daily_tag_coverage":["system.billing.list_prices","system.billing.usage"],"daily_dbsql_source":[],"daily_aiml_endpoints":["system.billing.list_prices","system.billing.usage"],"daily_dbsql_top":[],"daily_user_spend":["system.billing.list_prices","system.billing.usage"],"daily_untagged_objects":["system.billing.list_prices","system.billing.usage","system.compute.clusters","system.compute.warehouses"],"daily_aiml_models":["system.billing.list_prices","system.billing.usage","system.compute.clusters"],"daily_aiml_ml_clusters":["system.billing.list_prices","system.billing.usage","system.compute.clusters"],"daily_aiml_agents":["system.billing.list_prices","system.billing.usage","system.serving.served_entities"],"daily_object_spend":["system.billing.list_prices","system.billing.usage"],"daily_infra_cluster_spend":["system.access.workspaces_latest","system.billing.usage","system.compute.clusters"],"daily_dbsql_warehouse_type":["system.access.workspaces_latest","system.billing.list_prices","system.billing.usage","system.compute.warehouses"],"daily_dbsql_region_scope":["system.billing.usage","system.compute.warehouses"],"warehouse_optimizer_findings":["system.compute.warehouse_events","system.compute.warehouses","system.query.history"],"daily_warehouse_idle":["system.billing.list_prices","system.billing.usage","system.compute.warehouse_events","system.compute.warehouses","system.query.history"],"daily_kpi_facts":["system.billing.usage"],"daily_lakeflow_stats":["system.lakeflow.job_run_timeline"],"daily_query_users":["system.query.history"],"daily_apps_identities":["system.billing.usage"],"use_case_query_objects":["system.query.history"],"use_case_dashboard_objects":["system.dashboards.dashboards"],"daily_ai_gateway":[]}')
OPTIONAL_TABLES = set(json.loads('["daily_ai_gateway","use_case_dashboard_objects"]'))
CORE_TABLES = json.loads('["daily_usage_summary","daily_product_breakdown","daily_workspace_breakdown","sql_tool_attribution","daily_query_stats","dbsql_cost_per_query","daily_tag_summary","daily_apps_summary"]')
INVOICE_GOLD = json.loads('["daily_cloud_actuals","daily_azure_actuals","daily_gcp_actuals"]')
OPTIONAL_WIDGETS = {
    "daily_ai_gateway": ("ai_gateway_table", AI_GATEWAY_TABLE),  # Unity Gateway usage table FQN
}
CURRENT_IDENTITY = spark.sql("SELECT current_user() AS principal").first()["principal"]
missing_access = []
for source_table in SOURCE_TABLES:
    try:
        spark.sql(f"SELECT * FROM {source_table} LIMIT 0").collect()
    except Exception as exc:
        missing_access.append((source_table, str(exc)))

if missing_access:
    display(
        spark.createDataFrame(
            missing_access,
            "source_table STRING, error STRING",
        )
    )
    principal = str(CURRENT_IDENTITY).replace("`", "``")
    schemas = sorted({".".join(table.split(".")[:2]) for table, _ in missing_access})
    grant_lines = ["-- Run as a metastore admin:"]
    grant_lines.append(f"GRANT USE CATALOG ON CATALOG system TO `{principal}`;")
    for schema_name in schemas:
        grant_lines.append(
            f"GRANT USE SCHEMA ON SCHEMA {schema_name} TO `{principal}`;"
        )
    for table_name, _ in missing_access:
        grant_lines.append(
            f"GRANT SELECT ON TABLE {table_name} TO `{principal}`;"
        )
    print("\n".join(grant_lines))
    print(
        "Continuing with partial capability. Gold tables that depend on inaccessible "
        "system tables will be skipped."
    )
else:
    print(f"Permission preflight passed for {len(SOURCE_TABLES)} system tables.")

# COMMAND ----------

TABLE_SQL = json.loads('{"daily_usage_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_usage_summary` CLUSTER BY (usage_date, workspace_id) AS\\nWITH usage_with_price AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.sku_name,\\n    u.billing_origin_product,\\n    u.usage_quantity,\\n    u.identity_metadata.run_as AS run_as,\\n    COALESCE(p.pricing.default, 0) as price_per_dbu,\\n    COALESCE(p.pricing.effective_list.default, p.pricing.default, 0) as effective_price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name\\n    AND u.cloud = p.cloud\\n    AND p.price_end_time IS NULL\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  SUM(usage_quantity) as total_dbus,\\n  SUM(usage_quantity * price_per_dbu) as total_spend,\\n  SUM(usage_quantity * effective_price_per_dbu) as effective_list_spend,\\n  SUM(CASE WHEN run_as IS NOT NULL THEN usage_quantity * price_per_dbu ELSE 0 END) as user_attributed_spend\\nFROM usage_with_price\\nGROUP BY usage_date, workspace_id\\nORDER BY usage_date, workspace_id","daily_product_breakdown":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_product_breakdown` CLUSTER BY (usage_date, workspace_id) AS\\nWITH usage_with_price AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.sku_name,\\n    u.billing_origin_product,\\n    u.usage_quantity,\\n    u.usage_metadata,\\n    COALESCE(p.pricing.default, 0) as price_per_dbu,\\n    COALESCE(p.pricing.effective_list.default, p.pricing.default, 0) as effective_price_per_dbu,\\n    CASE\\n      WHEN u.billing_origin_product = \'SQL\' THEN \'SQL\'\\n      WHEN u.billing_origin_product = \'DLT\' OR u.usage_metadata.dlt_pipeline_id IS NOT NULL THEN \'ETL - Streaming\'\\n      WHEN u.billing_origin_product = \'JOBS\' THEN \'ETL - Batch\'\\n      WHEN u.sku_name LIKE \'%ALL_PURPOSE%\' THEN \'Interactive\'\\n      WHEN u.billing_origin_product = \'SERVING\' OR u.billing_origin_product = \'MODEL_SERVING\'\\n           OR u.sku_name LIKE \'%SERVING%\' OR u.sku_name LIKE \'%INFERENCE%\'\\n           OR u.sku_name LIKE \'%PROVISIONED_THROUGHPUT%\' THEN \'Model Serving\'\\n      WHEN u.sku_name LIKE \'%VECTOR_SEARCH%\' THEN \'AI Search\'\\n      WHEN u.sku_name LIKE \'%FOUNDATION_MODEL%\' OR u.sku_name LIKE \'%FINE_TUNING%\' THEN \'Fine-Tuning\'\\n      WHEN u.sku_name LIKE \'%AI_BI%\' OR u.sku_name LIKE \'%AI_QUERY%\'\\n           OR u.sku_name LIKE \'%AI_FUNCTIONS%\' THEN \'AI Functions\'\\n      WHEN u.sku_name LIKE \'%SERVERLESS%\' AND u.billing_origin_product NOT IN (\'JOBS\', \'SQL\', \'DLT\') THEN \'Serverless\'\\n      ELSE \'Other\'\\n    END as product_category\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name\\n    AND u.cloud = p.cloud\\n    AND p.price_end_time IS NULL\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  product_category,\\n  SUM(usage_quantity) as total_dbus,\\n  SUM(usage_quantity * price_per_dbu) as total_spend,\\n  SUM(usage_quantity * effective_price_per_dbu) as effective_list_spend\\nFROM usage_with_price\\nGROUP BY usage_date, workspace_id, product_category\\nORDER BY usage_date, workspace_id, product_category","daily_workspace_breakdown":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_workspace_breakdown` CLUSTER BY (usage_date, workspace_id) AS\\nWITH usage_with_price AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.sku_name,\\n    u.usage_quantity,\\n    COALESCE(p.pricing.default, 0) as price_per_dbu,\\n    COALESCE(p.pricing.effective_list.default, p.pricing.default, 0) as effective_price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name\\n    AND u.cloud = p.cloud\\n    AND p.price_end_time IS NULL\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n)\\nSELECT\\n  uwp.usage_date,\\n  uwp.workspace_id,\\n  ws.workspace_name,\\n  SUM(uwp.usage_quantity) as total_dbus,\\n  SUM(uwp.usage_quantity * uwp.price_per_dbu) as total_spend,\\n  SUM(uwp.usage_quantity * uwp.effective_price_per_dbu) as effective_list_spend\\nFROM usage_with_price uwp\\nLEFT JOIN system.access.workspaces_latest ws ON uwp.workspace_id = ws.workspace_id\\nGROUP BY uwp.usage_date, uwp.workspace_id, ws.workspace_name\\nORDER BY uwp.usage_date, uwp.workspace_id","sql_tool_attribution":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`sql_tool_attribution` CLUSTER BY (usage_date, workspace_id) AS\\nWITH sql_query_work AS (\\n  SELECT\\n    CASE\\n      WHEN client_application LIKE \'%Genie%\' THEN \'Genie\'\\n      ELSE \'DBSQL\'\\n    END AS sql_product,\\n    DATE(start_time) AS usage_date,\\n    workspace_id,\\n    compute.warehouse_id AS warehouse_id,\\n    SUM(total_task_duration_ms) AS work_ms\\n  FROM system.query.history\\n  WHERE executed_as_user_id IS NOT NULL\\n    AND compute.warehouse_id IS NOT NULL\\n    AND DATE(start_time) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  GROUP BY 1, 2, 3, 4\\n),\\nsql_usage AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.usage_metadata.warehouse_id as warehouse_id,\\n    SUM(u.usage_quantity) as total_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) as total_spend,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.effective_list.default, p.pricing.default, 0)) as effective_list_spend\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name\\n    AND u.cloud = p.cloud\\n    AND p.price_end_time IS NULL\\n  WHERE u.billing_origin_product = \'SQL\'\\n    AND u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n  GROUP BY 1, 2, 3\\n),\\nwarehouse_totals AS (\\n  SELECT\\n    usage_date,\\n    workspace_id,\\n    warehouse_id,\\n    SUM(work_ms) as total_work_ms\\n  FROM sql_query_work\\n  GROUP BY usage_date, workspace_id, warehouse_id\\n)\\nSELECT\\n  q.sql_product,\\n  q.usage_date,\\n  q.workspace_id,\\n  q.warehouse_id,\\n  CASE\\n    WHEN w.total_work_ms > 0 THEN (q.work_ms / w.total_work_ms) * s.total_dbus\\n    ELSE 0\\n  END as attributed_dbus,\\n  CASE\\n    WHEN w.total_work_ms > 0 THEN (q.work_ms / w.total_work_ms) * s.total_spend\\n    ELSE 0\\n  END as attributed_spend,\\n  CASE\\n    WHEN w.total_work_ms > 0 THEN (q.work_ms / w.total_work_ms) * s.effective_list_spend\\n    ELSE 0\\n  END as attributed_effective_list_spend\\nFROM sql_query_work q\\nJOIN warehouse_totals w ON q.usage_date = w.usage_date AND q.workspace_id = w.workspace_id AND q.warehouse_id = w.warehouse_id\\nLEFT JOIN sql_usage s ON q.usage_date = s.usage_date AND q.workspace_id = s.workspace_id AND q.warehouse_id = s.warehouse_id","daily_query_stats":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_query_stats` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  DATE(start_time) as usage_date,\\n  workspace_id,\\n  COUNT(*) as total_queries,\\n  COUNT(DISTINCT COALESCE(executed_by, executed_as_user_id)) as unique_query_users,\\n  SUM(COALESCE(read_rows, 0)) as total_rows_read,\\n  SUM(COALESCE(read_bytes, 0)) as total_bytes_read,\\n  SUM(COALESCE(total_task_duration_ms, 0)) / 1000.0 as total_compute_seconds\\nFROM system.query.history\\nWHERE DATE(start_time) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\nGROUP BY DATE(start_time), workspace_id\\nORDER BY usage_date, workspace_id","dbsql_cost_per_query":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`dbsql_cost_per_query` CLUSTER BY (query_date, workspace_id) AS\\nWITH\\n-- Get hourly DBU usage per warehouse from billing\\nwarehouse_hourly_usage AS (\\n  SELECT\\n    DATE_TRUNC(\'hour\', u.usage_start_time) AS hour_bucket,\\n    u.usage_metadata.warehouse_id AS warehouse_id,\\n    SUM(u.usage_quantity) AS hourly_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS hourly_dollars,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.effective_list.default, p.pricing.default, 0)) AS hourly_dollars_effective\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name\\n    AND u.cloud = p.cloud\\n    AND p.price_end_time IS NULL\\n  WHERE u.billing_origin_product = \'SQL\'\\n    AND u.usage_metadata.warehouse_id IS NOT NULL\\n    AND u.usage_start_time >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  GROUP BY 1, 2\\n),\\n-- Get all queries with their execution details\\nqueries_with_details AS (\\n  SELECT\\n    q.statement_id,\\n    q.statement_text,\\n    COALESCE(q.executed_by, q.executed_as_user_id) AS executed_by,\\n    q.compute.warehouse_id AS warehouse_id,\\n    q.workspace_id,\\n    q.start_time,\\n    q.end_time,\\n    (UNIX_TIMESTAMP(q.end_time) - UNIX_TIMESTAMP(q.start_time)) AS duration_seconds,\\n    q.total_task_duration_ms,\\n    q.client_application,\\n    -- Determine query source type from client_application and other fields\\n    CASE\\n      WHEN q.client_application LIKE \'%genie%\' OR q.client_application LIKE \'%Genie%\' THEN \'GENIE SPACE\'\\n      WHEN q.client_application LIKE \'%dashboard%\' OR q.client_application LIKE \'%Dashboard%\' THEN\\n        CASE\\n          WHEN q.client_application LIKE \'%lakeview%\' OR q.client_application LIKE \'%aibi%\' THEN \'AI/BI DASHBOARD\'\\n          ELSE \'LEGACY DASHBOARD\'\\n        END\\n      WHEN q.client_application LIKE \'%notebook%\' OR q.client_application LIKE \'%Notebook%\' THEN \'NOTEBOOK\'\\n      WHEN q.client_application LIKE \'%job%\' OR q.client_application LIKE \'%Job%\' OR q.statement_type = \'JOB\' THEN \'JOB\'\\n      WHEN q.client_application LIKE \'%alert%\' OR q.client_application LIKE \'%Alert%\' THEN \'ALERT\'\\n      WHEN q.client_application LIKE \'%sql-editor%\' OR q.client_application LIKE \'%SQL Editor%\' THEN \'SQL QUERY\'\\n      ELSE \'SQL QUERY\'\\n    END AS query_source_type,\\n    -- Extract source ID where possible\\n    CASE\\n      WHEN q.client_application LIKE \'%genie%\' THEN REGEXP_EXTRACT(q.client_application, \'genie[/-]([a-zA-Z0-9-]+)\', 1)\\n      WHEN q.client_application LIKE \'%dashboard%\' THEN REGEXP_EXTRACT(q.client_application, \'dashboard[/-]([a-zA-Z0-9-]+)\', 1)\\n      ELSE NULL\\n    END AS query_source_id\\n  FROM system.query.history q\\n  WHERE q.compute.warehouse_id IS NOT NULL\\n    AND q.start_time >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND q.statement_type != \'CANCEL\'\\n    AND (q.executed_by IS NOT NULL OR q.executed_as_user_id IS NOT NULL)\\n),\\n-- Calculate total work per warehouse per hour for proportional allocation\\nwarehouse_hourly_work AS (\\n  SELECT\\n    DATE_TRUNC(\'hour\', start_time) AS hour_bucket,\\n    warehouse_id,\\n    SUM(COALESCE(total_task_duration_ms, duration_seconds * 1000)) AS total_work_ms\\n  FROM queries_with_details\\n  GROUP BY 1, 2\\n),\\n-- Attribute costs to each query proportionally based on work done\\nquery_costs AS (\\n  SELECT\\n    q.statement_id,\\n    q.statement_text,\\n    q.executed_by,\\n    q.warehouse_id,\\n    q.workspace_id,\\n    q.start_time,\\n    q.end_time,\\n    q.duration_seconds,\\n    q.client_application,\\n    q.query_source_type,\\n    q.query_source_id,\\n    q.total_task_duration_ms,\\n    DATE_TRUNC(\'hour\', q.start_time) AS query_hour,\\n    -- Proportional cost attribution\\n    CASE\\n      WHEN w.total_work_ms > 0 THEN\\n        (COALESCE(q.total_task_duration_ms, q.duration_seconds * 1000) / w.total_work_ms) * h.hourly_dbus\\n      ELSE 0\\n    END AS query_attributed_dbus_estimation,\\n    CASE\\n      WHEN w.total_work_ms > 0 THEN\\n        (COALESCE(q.total_task_duration_ms, q.duration_seconds * 1000) / w.total_work_ms) * h.hourly_dollars\\n      ELSE 0\\n    END AS query_attributed_dollars_estimation,\\n    CASE\\n      WHEN w.total_work_ms > 0 THEN\\n        (COALESCE(q.total_task_duration_ms, q.duration_seconds * 1000) / w.total_work_ms) * h.hourly_dollars_effective\\n      ELSE 0\\n    END AS query_attributed_dollars_effective\\n  FROM queries_with_details q\\n  LEFT JOIN warehouse_hourly_work w\\n    ON DATE_TRUNC(\'hour\', q.start_time) = w.hour_bucket\\n    AND q.warehouse_id = w.warehouse_id\\n  LEFT JOIN warehouse_hourly_usage h\\n    ON DATE_TRUNC(\'hour\', q.start_time) = h.hour_bucket\\n    AND q.warehouse_id = h.warehouse_id\\n)\\nSELECT\\n  statement_id,\\n  query_source_id,\\n  query_source_type,\\n  client_application,\\n  executed_by,\\n  warehouse_id,\\n  statement_text,\\n  CAST(workspace_id AS STRING) AS workspace_id,\\n  start_time,\\n  end_time,\\n  duration_seconds,\\n  query_attributed_dollars_estimation,\\n  query_attributed_dbus_estimation,\\n  -- Generate query profile URL (customers should customize host)\\n  CONCAT(\\n    \'https://DATABRICKS_HOST/sql/history?o=\',\\n    CAST(workspace_id AS STRING),\\n    \'&queryId=\',\\n    statement_id,\\n    \'&queryStartTimeMs=\',\\n    CAST(UNIX_TIMESTAMP(start_time) * 1000 AS BIGINT)\\n  ) AS query_profile_url,\\n  -- Generate source URL for dashboards/genie spaces\\n  CASE\\n    WHEN query_source_type = \'GENIE SPACE\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/genie/rooms/\', query_source_id)\\n    WHEN query_source_type = \'AI/BI DASHBOARD\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/sql/dashboardsv3/\', query_source_id)\\n    WHEN query_source_type = \'LEGACY DASHBOARD\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/sql/dashboards/\', query_source_id)\\n    WHEN query_source_type = \'SQL QUERY\' AND query_source_id IS NOT NULL THEN\\n      CONCAT(\'https://DATABRICKS_HOST/editor/queries/\', query_source_id)\\n    ELSE NULL\\n  END AS url_helper,\\n  DATE(start_time) AS query_date\\nFROM query_costs\\nWHERE query_attributed_dollars_estimation > 0\\n   OR query_attributed_dbus_estimation > 0\\n   OR duration_seconds > 0\\nORDER BY start_time DESC","daily_tag_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_tag_summary` CLUSTER BY (usage_date, tag_key) AS\\nWITH tagged_usage AS (\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.usage_quantity,\\n    u.custom_tags,\\n    COALESCE(p.pricing.default, 0) AS price_per_dbu\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name\\n    AND u.cloud = p.cloud\\n    AND p.price_end_time IS NULL\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n    AND u.custom_tags IS NOT NULL\\n    AND size(u.custom_tags) > 0\\n),\\nexploded AS (\\n  SELECT\\n    usage_date,\\n    workspace_id,\\n    usage_quantity,\\n    price_per_dbu,\\n    tag_key,\\n    tag_value\\n  FROM tagged_usage\\n  LATERAL VIEW EXPLODE(custom_tags) t AS tag_key, tag_value\\n)\\nSELECT\\n  usage_date,\\n  workspace_id,\\n  tag_key,\\n  tag_value,\\n  SUM(usage_quantity)                    AS total_dbus,\\n  SUM(usage_quantity * price_per_dbu)    AS total_spend,\\n  COUNT(*)                               AS usage_row_count\\nFROM exploded\\nGROUP BY usage_date, workspace_id, tag_key, tag_value\\nORDER BY usage_date, tag_key, tag_value","daily_apps_summary":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_apps_summary` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  COALESCE(u.usage_metadata.app_id, \'Unknown\') AS app_id,\\n  u.sku_name,\\n  SUM(u.usage_quantity)                              AS total_dbus,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\nFROM system.billing.usage u\\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name\\n  AND u.cloud = p.cloud\\n  AND p.price_end_time IS NULL\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\n  AND u.billing_origin_product = \'APPS\'\\nGROUP BY u.usage_date, u.workspace_id, COALESCE(u.usage_metadata.app_id, \'Unknown\'), u.sku_name\\nORDER BY u.usage_date, u.workspace_id","daily_sku_breakdown":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_sku_breakdown` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  u.sku_name,\\n  u.billing_origin_product,\\n  u.usage_type,\\n  CASE\\n    WHEN u.sku_name LIKE \'%ANTHROPIC%\' THEN \'FMAPI - Anthropic\'\\n    WHEN u.sku_name LIKE \'%OPENAI%\' THEN \'FMAPI - OpenAI\'\\n    WHEN u.sku_name LIKE \'%GEMINI%\' THEN \'FMAPI - Gemini\'\\n    WHEN u.sku_name LIKE \'%SERVERLESS_REAL_TIME_INFERENCE%\' THEN \'Serverless Inference\'\\n    WHEN u.product_features.model_serving.offering_type = \'BATCH_INFERENCE\' THEN \'Batch Inference\'\\n    WHEN u.billing_origin_product = \'VECTOR_SEARCH\' THEN \'AI Search\'\\n    WHEN u.sku_name LIKE \'%FINE_TUNING%\' THEN \'Fine Tuning\'\\n    WHEN u.billing_origin_product = \'MODEL_SERVING\' THEN \'Model Serving\'\\n    WHEN u.sku_name LIKE \'%VECTOR_SEARCH%\' THEN \'AI Search\'\\n    ELSE \'Other AI/ML\'\\n  END AS aiml_category,\\n  CASE\\n    WHEN u.billing_origin_product = \'GENIE\' OR u.sku_name ILIKE \'%GENIE%\' OR u.sku_name ILIKE \'%AI_BI_GENIE%\' THEN\\n      CASE\\n        WHEN get_json_object(to_json(u.usage_metadata), \'$.genie.surface\') = \'GENIE_CODE\' OR u.sku_name ILIKE \'%GENIE_CODE%\' THEN \'genie_code\'\\n        WHEN get_json_object(to_json(u.usage_metadata), \'$.genie.surface\') = \'GENIE_ONE\' OR u.sku_name ILIKE \'%GENIE_ONE%\' THEN \'genie_one\'\\n        WHEN get_json_object(to_json(u.usage_metadata), \'$.genie.surface\') = \'GENIE_AGENTS\' OR u.sku_name ILIKE \'%GENIE_AGENTS%\' THEN \'genie_agents\'\\n        ELSE \'unknown\'\\n      END\\n    ELSE NULL\\n  END AS genie_surface,\\n  CASE\\n    WHEN u.usage_type IN (\'BILLABLE\', \'TOKEN\') THEN \'charged\'\\n    WHEN u.usage_type IN (\'NON_BILLABLE\', \'RELATED\') THEN \'free_tier\'\\n    ELSE \'other\'\\n  END AS charge_class,\\n  SUM(u.usage_quantity) AS total_dbus,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\nFROM system.billing.usage u\\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\nGROUP BY 1, 2, 3, 4, 5, 6, 7, 8","daily_job_pipeline_spend":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_job_pipeline_spend` CLUSTER BY (usage_date, workspace_id) AS\\nWITH pipeline_info AS (\\n  SELECT pipeline_id, MAX(name) AS pipeline_name, MAX(created_by) AS creator_name\\n  FROM system.lakeflow.pipelines\\n  GROUP BY pipeline_id\\n)\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  CASE\\n    WHEN u.usage_metadata.dlt_pipeline_id IS NOT NULL THEN \'SDP Pipeline\'\\n    WHEN u.usage_metadata.job_id IS NOT NULL THEN \'Job\'\\n    ELSE \'Unknown\'\\n  END AS object_type,\\n  COALESCE(u.usage_metadata.dlt_pipeline_id, u.usage_metadata.job_id) AS object_id,\\n  COALESCE(pi.pipeline_name, u.usage_metadata.job_name, u.usage_metadata.dlt_pipeline_id, u.usage_metadata.job_id) AS object_name,\\n  COALESCE(MAX(pi.creator_name), MAX(u.identity_metadata.run_as)) AS owner,\\n  SUM(u.usage_quantity) AS total_dbus,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend,\\n  COUNT(DISTINCT u.usage_metadata.job_run_id) AS total_runs\\nFROM system.billing.usage u\\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\nLEFT JOIN pipeline_info pi ON u.usage_metadata.dlt_pipeline_id = pi.pipeline_id\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\n  AND (u.billing_origin_product IN (\'JOBS\', \'DLT\') OR u.usage_metadata.dlt_pipeline_id IS NOT NULL)\\n  AND (u.usage_metadata.dlt_pipeline_id IS NOT NULL OR u.usage_metadata.job_id IS NOT NULL)\\nGROUP BY 1, 2, 3, 4, 5","daily_interactive_spend":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_interactive_spend` CLUSTER BY (usage_date, workspace_id) AS\\nWITH cluster_info AS (\\n  SELECT cluster_id, MAX(cluster_name) AS cluster_name\\n  FROM system.compute.clusters\\n  GROUP BY cluster_id\\n)\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  u.usage_metadata.cluster_id AS cluster_id,\\n  MAX(ci.cluster_name) AS cluster_name,\\n  u.usage_metadata.notebook_path AS notebook_path,\\n  u.identity_metadata.run_as AS run_as_user,\\n  SUM(u.usage_quantity) AS total_dbus,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend,\\n  COUNT(DISTINCT u.usage_metadata.notebook_id) AS notebook_count\\nFROM system.billing.usage u\\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\nLEFT JOIN cluster_info ci ON u.usage_metadata.cluster_id = ci.cluster_id\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\n  AND u.sku_name LIKE \'%ALL_PURPOSE%\'\\nGROUP BY 1, 2, 3, 5, 6","daily_tag_coverage":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_tag_coverage` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend,\\n  SUM(CASE WHEN u.custom_tags IS NOT NULL THEN u.usage_quantity * COALESCE(p.pricing.default, 0) ELSE 0 END) AS tagged_spend\\nFROM system.billing.usage u\\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\nGROUP BY u.usage_date, u.workspace_id","daily_dbsql_source":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_dbsql_source` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  CAST(start_time AS DATE) AS usage_date,\\n  workspace_id,\\n  query_source_type,\\n  warehouse_id,\\n  executed_by,\\n  COUNT(*) AS query_count,\\n  SUM(query_attributed_dollars_estimation) AS total_spend,\\n  SUM(query_attributed_dbus_estimation) AS total_dbus,\\n  AVG(duration_seconds) AS avg_duration_seconds\\nFROM `{catalog}`.`{schema}`.`dbsql_cost_per_query`\\nWHERE CAST(start_time AS DATE) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\nGROUP BY 1, 2, 3, 4, 5","daily_aiml_endpoints":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_aiml_endpoints` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  COALESCE(u.usage_metadata.endpoint_name, \'UNKNOWN\') AS endpoint_name,\\n  u.sku_name,\\n  CASE WHEN u.sku_name LIKE \'%LAUNCH%\' THEN \'Launch (Scale-from-Zero)\' ELSE \'Steady State\' END AS cost_type,\\n  SUM(u.usage_quantity) AS total_dbus,\\n  SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\nFROM system.billing.usage u\\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\n  AND u.sku_name LIKE \'%SERVERLESS_REAL_TIME_INFERENCE%\'\\nGROUP BY 1, 2, 3, 4, 5","daily_dbsql_top":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_dbsql_top` CLUSTER BY (usage_date) AS\\nSELECT\\n  CAST(start_time AS DATE) AS usage_date,\\n  statement_id,\\n  query_source_type,\\n  executed_by,\\n  warehouse_id,\\n  workspace_id,\\n  SUBSTRING(statement_text, 1, 200) AS statement_preview,\\n  duration_seconds,\\n  query_attributed_dollars_estimation AS cost,\\n  query_attributed_dbus_estimation AS dbus,\\n  query_profile_url,\\n  url_helper AS source_url,\\n  start_time,\\n  end_time\\nFROM (\\n  SELECT\\n    *,\\n    ROW_NUMBER() OVER (\\n      PARTITION BY CAST(start_time AS DATE)\\n      ORDER BY query_attributed_dollars_estimation DESC\\n    ) AS rn\\n  FROM `{catalog}`.`{schema}`.`dbsql_cost_per_query`\\n  WHERE CAST(start_time AS DATE) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n) ranked\\nWHERE rn <= 50","daily_user_spend":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_user_spend` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    u.identity_metadata.run_as AS user_email,\\n\\n    CASE\\n      WHEN u.billing_origin_product = \'SQL\' THEN \'SQL\'\\n      WHEN u.billing_origin_product = \'DLT\' OR u.usage_metadata.dlt_pipeline_id IS NOT NULL THEN \'ETL - Streaming\'\\n      WHEN u.billing_origin_product = \'JOBS\' THEN \'ETL - Batch\'\\n      WHEN u.sku_name LIKE \'%ALL_PURPOSE%\' THEN \'Interactive\'\\n      WHEN u.billing_origin_product IN (\'SERVING\', \'MODEL_SERVING\')\\n           OR u.sku_name LIKE \'%SERVING%\' OR u.sku_name LIKE \'%INFERENCE%\'\\n           OR u.sku_name LIKE \'%PROVISIONED_THROUGHPUT%\' THEN \'Model Serving\'\\n      WHEN u.sku_name LIKE \'%VECTOR_SEARCH%\' THEN \'AI Search\'\\n      WHEN u.sku_name LIKE \'%FOUNDATION_MODEL%\' OR u.sku_name LIKE \'%FINE_TUNING%\' THEN \'Fine-Tuning\'\\n      WHEN u.sku_name LIKE \'%AI_BI%\' OR u.sku_name LIKE \'%AI_QUERY%\'\\n           OR u.sku_name LIKE \'%AI_FUNCTIONS%\' THEN \'AI Functions\'\\n      WHEN u.sku_name LIKE \'%SERVERLESS%\'\\n           AND u.billing_origin_product NOT IN (\'SQL\', \'JOBS\', \'DLT\') THEN \'Serverless\'\\n      ELSE \'Other\'\\n    END\\n AS product_category,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend,\\n    SUM(u.usage_quantity) AS total_dbus\\n  FROM system.billing.usage u\\n  \\nLEFT JOIN system.billing.list_prices p\\n  ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n    AND u.identity_metadata.run_as IS NOT NULL\\n  GROUP BY 1, 2, 3, 4","daily_untagged_objects":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_untagged_objects` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT usage_date, workspace_id, object_type, object_id, MAX(object_name) AS object_name,\\n         MAX(owner) AS owner, MAX(extra) AS extra,\\n         SUM(total_dbus) AS total_dbus, SUM(total_spend) AS total_spend\\n  FROM (\\n    SELECT\\n      u.usage_date, u.workspace_id, \'cluster\' AS object_type,\\n      CAST(u.usage_metadata.cluster_id AS STRING) AS object_id,\\n      COALESCE(ci.cluster_name, CAST(u.usage_metadata.cluster_id AS STRING)) AS object_name,\\n      ci.owned_by AS owner, ci.cluster_source AS extra,\\n      u.usage_quantity AS total_dbus,\\n      u.usage_quantity * COALESCE(p.pricing.default, 0) AS total_spend\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p\\n      ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    LEFT JOIN (\\n      SELECT cluster_id, MAX(cluster_name) AS cluster_name, MAX(cluster_source) AS cluster_source, MAX(owned_by) AS owned_by\\n      FROM system.compute.clusters WHERE delete_time IS NULL GROUP BY cluster_id\\n    ) ci ON u.usage_metadata.cluster_id = ci.cluster_id\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.cluster_id IS NOT NULL\\n      AND (u.custom_tags IS NULL OR size(u.custom_tags) = 0)\\n    UNION ALL\\n    SELECT\\n      u.usage_date, u.workspace_id, \'job\', CAST(u.usage_metadata.job_id AS STRING),\\n      COALESCE(u.usage_metadata.job_name, CAST(u.usage_metadata.job_id AS STRING)),\\n      CAST(NULL AS STRING), CAST(NULL AS STRING),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p\\n      ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.job_id IS NOT NULL\\n      AND (u.custom_tags IS NULL OR size(u.custom_tags) = 0)\\n    UNION ALL\\n    SELECT\\n      u.usage_date, u.workspace_id, \'pipeline\', CAST(u.usage_metadata.dlt_pipeline_id AS STRING),\\n      CAST(u.usage_metadata.dlt_pipeline_id AS STRING),\\n      CAST(NULL AS STRING), CAST(NULL AS STRING),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p\\n      ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.dlt_pipeline_id IS NOT NULL\\n      AND (u.custom_tags IS NULL OR size(u.custom_tags) = 0)\\n    UNION ALL\\n    SELECT\\n      u.usage_date, u.workspace_id, \'warehouse\', CAST(u.usage_metadata.warehouse_id AS STRING),\\n      COALESCE(wi.warehouse_name, CAST(u.usage_metadata.warehouse_id AS STRING)),\\n      CAST(NULL AS STRING), CAST(NULL AS STRING),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p\\n      ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    LEFT JOIN (\\n      SELECT warehouse_id, MAX(warehouse_name) AS warehouse_name\\n      FROM system.compute.warehouses WHERE delete_time IS NULL GROUP BY warehouse_id\\n    ) wi ON u.usage_metadata.warehouse_id = wi.warehouse_id\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.warehouse_id IS NOT NULL\\n      AND (u.custom_tags IS NULL OR size(u.custom_tags) = 0)\\n    UNION ALL\\n    SELECT\\n      u.usage_date, u.workspace_id, \'endpoint\', COALESCE(u.usage_metadata.endpoint_name, u.usage_metadata.endpoint_id),\\n      COALESCE(u.usage_metadata.endpoint_name, u.usage_metadata.endpoint_id),\\n      CAST(NULL AS STRING), CAST(NULL AS STRING),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p\\n      ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0\\n      AND (u.usage_metadata.endpoint_name IS NOT NULL OR u.usage_metadata.endpoint_id IS NOT NULL)\\n      AND (u.custom_tags IS NULL OR size(u.custom_tags) = 0)\\n  ) raw\\n  GROUP BY usage_date, workspace_id, object_type, object_id","daily_aiml_models":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_aiml_models` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT * FROM (\\n\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    COALESCE(\\n      u.usage_metadata.endpoint_name,\\n      cn.cluster_name,\\n      CASE WHEN u.usage_metadata.job_id IS NOT NULL THEN CONCAT(\'Job #\', CAST(u.usage_metadata.job_id AS STRING)) END,\\n      CAST(u.usage_metadata.cluster_id AS STRING),\\n      CASE WHEN u.sku_name LIKE \'%FEATURE%\' THEN \'Feature Store Run\'\\n           WHEN u.sku_name LIKE \'%TRAINING%\' THEN \'Serverless Fine-tuning\' END,\\n      \'Unknown\'\\n    ) AS model_name,\\n    CASE\\n      WHEN u.sku_name LIKE \'%FEATURE%\' THEN \'Feature Store\'\\n      WHEN u.sku_name LIKE \'%TRAINING%\' THEN \'Model Training\'\\n      WHEN u.sku_name LIKE \'%ANTHROPIC%\' OR u.sku_name LIKE \'%OPENAI%\'\\n           OR u.sku_name LIKE \'%GEMINI%\' OR u.sku_name LIKE \'%META%\'\\n           OR u.sku_name LIKE \'%COHERE%\' OR u.sku_name LIKE \'%MISTRAL%\'\\n           OR u.sku_name LIKE \'%AI21%\' OR u.sku_name LIKE \'%MOSAIC%\'\\n           OR u.sku_name LIKE \'%DBRX%\' OR u.sku_name LIKE \'%LLAMA%\'\\n           OR u.billing_origin_product = \'FOUNDATION_MODEL_SERVING\' THEN \'Foundation Model API\'\\n      ELSE NULL\\n    END AS model_type,\\n    SUM(u.usage_quantity) AS total_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n  LEFT JOIN (\\n    SELECT cluster_id, MAX(cluster_name) AS cluster_name FROM system.compute.clusters GROUP BY cluster_id\\n  ) cn ON u.usage_metadata.cluster_id = cn.cluster_id\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0\\n    AND (\\n      u.sku_name LIKE \'%FEATURE%\' OR u.sku_name LIKE \'%TRAINING%\'\\n      OR u.sku_name LIKE \'%ANTHROPIC%\' OR u.sku_name LIKE \'%OPENAI%\'\\n      OR u.sku_name LIKE \'%GEMINI%\' OR u.sku_name LIKE \'%META%\'\\n      OR u.sku_name LIKE \'%COHERE%\' OR u.sku_name LIKE \'%MISTRAL%\'\\n      OR u.sku_name LIKE \'%AI21%\' OR u.sku_name LIKE \'%MOSAIC%\'\\n      OR u.sku_name LIKE \'%DBRX%\' OR u.sku_name LIKE \'%LLAMA%\'\\n      OR u.billing_origin_product = \'FOUNDATION_MODEL_SERVING\'\\n    )\\n  GROUP BY 1, 2, 3, 4\\n\\n) t WHERE model_type IS NOT NULL","daily_aiml_ml_clusters":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_aiml_ml_clusters` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    cm.cluster_id,\\n    MAX(cm.cluster_name) AS cluster_name,\\n    MAX(cm.spark_version) AS runtime_version,\\n    MAX(cm.owned_by) AS owner,\\n    SUM(u.usage_quantity) AS total_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\n  FROM (\\n    SELECT c.cluster_id, MAX(c.cluster_name) AS cluster_name, MAX(c.dbr_version) AS spark_version, MAX(c.owned_by) AS owned_by\\n    FROM system.compute.clusters c\\n    WHERE c.dbr_version IS NOT NULL\\n      AND (LOWER(c.dbr_version) LIKE \'%-ml-%\' OR LOWER(c.dbr_version) LIKE \'%-gpu-%\')\\n    GROUP BY c.cluster_id\\n  ) cm\\n  INNER JOIN system.billing.usage u ON u.usage_metadata.cluster_id = cm.cluster_id\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0\\n  GROUP BY u.usage_date, u.workspace_id, cm.cluster_id","daily_aiml_agents":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_aiml_agents` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    COALESCE(se.endpoint_name, u.usage_metadata.endpoint_name, u.usage_metadata.endpoint_id, \'Unknown\') AS agent_name,\\n    MAX(u.usage_metadata.endpoint_id) AS endpoint_id,\\n    MAX(u.billing_origin_product) AS billing_origin_product,\\n    MAX(se.served_entity_name) AS served_entity_name,\\n    MAX(CASE\\n      WHEN u.billing_origin_product = \'SUPERVISOR_AGENT\' THEN \'Supervisor Agent\'\\n      WHEN u.billing_origin_product = \'KNOWLEDGE_AGENT\' THEN \'Knowledge Assistant\'\\n      WHEN u.billing_origin_product = \'AGENT_BRICKS\'\\n        AND u.product_features.agent_bricks.problem_type = \'AGENT_BRICKS_AI_CLASSIFY\' THEN \'AI Classify\'\\n      WHEN u.billing_origin_product = \'AGENT_BRICKS\'\\n        AND u.product_features.agent_bricks.problem_type = \'AGENT_BRICKS_AI_EXTRACT\' THEN \'AI Extract\'\\n      ELSE \'Agent\'\\n    END) AS agent_type,\\n    SUM(u.usage_quantity) AS total_dbus,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n  LEFT JOIN (\\n    SELECT endpoint_id AS serving_endpoint_id, MAX(endpoint_name) AS endpoint_name, MAX(served_entity_name) AS served_entity_name\\n    FROM system.serving.served_entities WHERE endpoint_id IS NOT NULL GROUP BY endpoint_id\\n  ) se ON u.usage_metadata.endpoint_id = se.serving_endpoint_id\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0\\n    AND u.billing_origin_product IN (\'AGENT_BRICKS\', \'SUPERVISOR_AGENT\', \'KNOWLEDGE_AGENT\')\\n  GROUP BY 1, 2, 3","daily_object_spend":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_object_spend` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT usage_date, workspace_id, object_type, object_id, MAX(object_name) AS object_name,\\n         SUM(total_dbus) AS total_dbus, SUM(total_spend) AS total_spend\\n  FROM (\\n    SELECT u.usage_date, u.workspace_id, \'cluster\' AS object_type,\\n      CAST(u.usage_metadata.cluster_id AS STRING) AS object_id,\\n      CAST(u.usage_metadata.cluster_id AS STRING) AS object_name,\\n      u.usage_quantity AS total_dbus, u.usage_quantity * COALESCE(p.pricing.default, 0) AS total_spend\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.cluster_id IS NOT NULL\\n    UNION ALL\\n    SELECT u.usage_date, u.workspace_id, \'warehouse\', CAST(u.usage_metadata.warehouse_id AS STRING),\\n      CAST(u.usage_metadata.warehouse_id AS STRING), u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.warehouse_id IS NOT NULL\\n    UNION ALL\\n    SELECT u.usage_date, u.workspace_id, \'job\', CAST(u.usage_metadata.job_id AS STRING),\\n      COALESCE(u.usage_metadata.job_name, CAST(u.usage_metadata.job_id AS STRING)),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.job_id IS NOT NULL\\n    UNION ALL\\n    SELECT u.usage_date, u.workspace_id, \'endpoint\',\\n      COALESCE(u.usage_metadata.endpoint_id, u.usage_metadata.endpoint_name),\\n      COALESCE(u.usage_metadata.endpoint_name, u.usage_metadata.endpoint_id),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0\\n      AND (u.usage_metadata.endpoint_id IS NOT NULL OR u.usage_metadata.endpoint_name IS NOT NULL)\\n    UNION ALL\\n    SELECT u.usage_date, u.workspace_id, \'pipeline\', CAST(u.usage_metadata.dlt_pipeline_id AS STRING),\\n      CAST(u.usage_metadata.dlt_pipeline_id AS STRING),\\n      u.usage_quantity, u.usage_quantity * COALESCE(p.pricing.default, 0)\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.dlt_pipeline_id IS NOT NULL\\n  ) raw\\n  GROUP BY usage_date, workspace_id, object_type, object_id","daily_infra_cluster_spend":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_infra_cluster_spend` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT\\n    uf.usage_date,\\n    uf.workspace_id,\\n    uf.cluster_id,\\n    MAX(ci.cluster_name) AS cluster_name,\\n    MAX(ci.driver_instance_type) AS driver_instance_type,\\n    MAX(ci.worker_instance_type) AS worker_instance_type,\\n    MAX(ci.cluster_source) AS cluster_source,\\n    MAX(wsl.workspace_name) AS workspace_name,\\n    MAX(uf.cloud) AS cloud,\\n    SUM(uf.estimated_dbu_hours) AS total_dbu_hours\\n  FROM (\\n    SELECT u.usage_date, u.workspace_id, u.usage_metadata.cluster_id AS cluster_id, u.cloud, u.usage_quantity AS estimated_dbu_hours\\n    FROM system.billing.usage u\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.usage_metadata.cluster_id IS NOT NULL\\n      AND u.billing_origin_product NOT IN (\'SQL\', \'DLT\')\\n  ) uf\\n  LEFT JOIN (\\n    SELECT cluster_id, MAX(cluster_name) AS cluster_name, MAX(driver_node_type) AS driver_instance_type,\\n           MAX(worker_node_type) AS worker_instance_type, MAX(cluster_source) AS cluster_source\\n    FROM system.compute.clusters GROUP BY cluster_id\\n  ) ci ON uf.cluster_id = ci.cluster_id\\n  LEFT JOIN system.access.workspaces_latest wsl\\n    ON CAST(uf.workspace_id AS BIGINT) = CAST(wsl.workspace_id AS BIGINT)\\n  GROUP BY uf.usage_date, uf.workspace_id, uf.cluster_id","daily_dbsql_warehouse_type":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_dbsql_warehouse_type` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    CAST(u.usage_metadata.warehouse_id AS STRING) AS warehouse_id,\\n    MAX(w.warehouse_name) AS warehouse_name,\\n    MAX(COALESCE(w.warehouse_type, \'CLASSIC\')) AS warehouse_type,\\n    MAX(w.warehouse_size) AS warehouse_size,\\n    MAX(ws.workspace_name) AS workspace_name,\\n    SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS daily_spend,\\n    SUM(u.usage_quantity) AS daily_dbus\\n  FROM system.billing.usage u\\n  LEFT JOIN system.billing.list_prices p\\n    ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n  LEFT JOIN (\\n    SELECT warehouse_id, MAX(warehouse_name) AS warehouse_name, MAX(warehouse_type) AS warehouse_type,\\n           MAX(warehouse_size) AS warehouse_size, MAX(workspace_id) AS workspace_id\\n    FROM system.compute.warehouses GROUP BY warehouse_id\\n  ) w ON u.usage_metadata.warehouse_id = w.warehouse_id\\n  LEFT JOIN system.access.workspaces_latest ws ON u.workspace_id = ws.workspace_id\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_quantity > 0 AND u.billing_origin_product = \'SQL\'\\n    AND u.usage_metadata.warehouse_id IS NOT NULL\\n  GROUP BY u.usage_date, u.workspace_id, CAST(u.usage_metadata.warehouse_id AS STRING)","daily_dbsql_region_scope":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_dbsql_region_scope` AS\\nSELECT\\n  CURRENT_DATE() AS snapshot_date,\\n  (SELECT COUNT(DISTINCT workspace_id) FROM system.billing.usage\\n   WHERE billing_origin_product = \'SQL\' AND usage_quantity > 0\\n     AND usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n     AND workspace_id IS NOT NULL) AS billing_ws_count,\\n  (SELECT COUNT(DISTINCT workspace_id) FROM system.compute.warehouses\\n   WHERE workspace_id IS NOT NULL) AS compute_ws_count","warehouse_optimizer_findings":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`warehouse_optimizer_findings` AS\\nWITH current_warehouses AS (\\n  SELECT warehouse_id, warehouse_name, warehouse_size, workspace_id, warehouse_type\\n  FROM system.compute.warehouses\\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY warehouse_id ORDER BY change_time DESC) = 1\\n),\\nrecent_queries AS (\\n  SELECT DISTINCT compute.warehouse_id AS warehouse_id\\n  FROM system.query.history\\n  WHERE start_time >= NOW() - INTERVAL 24 HOUR AND compute.warehouse_id IS NOT NULL\\n),\\nrunning_warehouses AS (\\n  SELECT warehouse_id, MAX(event_time) AS last_event_time\\n  FROM system.compute.warehouse_events\\n  WHERE event_time >= NOW() - INTERVAL 2 HOUR AND cluster_count > 0\\n  GROUP BY warehouse_id\\n),\\nidle AS (\\n  SELECT rw.warehouse_id, w.warehouse_name, w.warehouse_size, w.workspace_id, w.warehouse_type,\\n         \'IDLE_RUNNING\' AS recommendation_type, CAST(rw.last_event_time AS STRING) AS extra_1,\\n         CAST(NULL AS DOUBLE) AS extra_n1, CAST(NULL AS DOUBLE) AS extra_n2, CAST(NULL AS BIGINT) AS extra_n3\\n  FROM running_warehouses rw\\n  JOIN current_warehouses w USING (warehouse_id)\\n  WHERE rw.warehouse_id NOT IN (SELECT warehouse_id FROM recent_queries)\\n    AND COALESCE(w.warehouse_type, \'CLASSIC\') != \'SERVERLESS\'\\n),\\ncluster_scale_events AS (\\n  SELECT warehouse_id, MAX(cluster_count) AS max_clusters_observed\\n  FROM system.compute.warehouse_events\\n  WHERE event_time >= NOW() - INTERVAL 30 DAY\\n  GROUP BY warehouse_id\\n  HAVING MAX(cluster_count) >= 2\\n),\\nmax_concurrency AS (\\n  SELECT warehouse_id, MAX(concurrent_queries) AS max_concurrent\\n  FROM (\\n    SELECT compute.warehouse_id AS warehouse_id, DATE_TRUNC(\'minute\', start_time) AS minute_bucket, COUNT(*) AS concurrent_queries\\n    FROM system.query.history\\n    WHERE start_time >= NOW() - INTERVAL 30 DAY\\n      AND compute.warehouse_id IN (SELECT warehouse_id FROM cluster_scale_events)\\n    GROUP BY 1, 2\\n  ) t\\n  GROUP BY 1\\n),\\nover_scaled AS (\\n  SELECT cse.warehouse_id, w.warehouse_name, w.warehouse_size, w.workspace_id, w.warehouse_type,\\n         \'OVER_SCALED\' AS recommendation_type, CAST(NULL AS STRING) AS extra_1,\\n         CAST(cse.max_clusters_observed AS DOUBLE) AS extra_n1,\\n         CAST(COALESCE(mc.max_concurrent, 0) AS DOUBLE) AS extra_n2,\\n         CAST(NULL AS BIGINT) AS extra_n3\\n  FROM cluster_scale_events cse\\n  JOIN current_warehouses w USING (warehouse_id)\\n  LEFT JOIN max_concurrency mc USING (warehouse_id)\\n  WHERE COALESCE(mc.max_concurrent, 0) < (cse.max_clusters_observed * 10)\\n),\\nlarge_warehouses AS (\\n  SELECT warehouse_id, warehouse_name, warehouse_size, workspace_id\\n  FROM current_warehouses\\n  WHERE warehouse_size IN (\'Large\', \'X-Large\', \'2X-Large\', \'3X-Large\', \'4X-Large\')\\n    AND COALESCE(warehouse_type, \'CLASSIC\') != \'SERVERLESS\'\\n),\\nqstats AS (\\n  SELECT compute.warehouse_id AS warehouse_id, COUNT(*) AS query_count,\\n    AVG(COALESCE(waiting_at_capacity_duration_ms, 0) + COALESCE(waiting_for_compute_duration_ms, 0)) AS avg_queue_ms,\\n    PERCENTILE_APPROX(\\n      GREATEST(0.0, (UNIX_TIMESTAMP(end_time) - UNIX_TIMESTAMP(start_time))\\n        - (COALESCE(waiting_at_capacity_duration_ms, 0) + COALESCE(waiting_for_compute_duration_ms, 0)) / 1000.0),\\n      0.5) AS median_duration_seconds\\n  FROM system.query.history\\n  WHERE start_time >= NOW() - INTERVAL 30 DAY\\n    AND compute.warehouse_id IN (SELECT warehouse_id FROM large_warehouses)\\n    AND end_time IS NOT NULL\\n  GROUP BY compute.warehouse_id\\n  HAVING COUNT(*) >= 5\\n),\\noversized AS (\\n  SELECT lw.warehouse_id, lw.warehouse_name, lw.warehouse_size, lw.workspace_id,\\n         CAST(NULL AS STRING) AS warehouse_type, \'OVERSIZED\' AS recommendation_type,\\n         CAST(NULL AS STRING) AS extra_1, q.avg_queue_ms AS extra_n1,\\n         q.median_duration_seconds AS extra_n2, q.query_count AS extra_n3\\n  FROM large_warehouses lw\\n  JOIN qstats q USING (warehouse_id)\\n  WHERE q.avg_queue_ms < 15000 AND q.median_duration_seconds < 180\\n)\\nSELECT CURRENT_DATE() AS snapshot_date, * FROM idle\\nUNION ALL SELECT CURRENT_DATE() AS snapshot_date, * FROM over_scaled\\nUNION ALL SELECT CURRENT_DATE() AS snapshot_date, * FROM oversized","daily_warehouse_idle":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_warehouse_idle` CLUSTER BY (usage_date, warehouse_id) AS\\n\\n  WITH date_spine AS (\\n    SELECT explode(sequence(DATE_SUB(CURRENT_DATE(), {billing_lookback_days}), CURRENT_DATE(), INTERVAL 1 DAY)) AS usage_date\\n  ),\\n  all_events AS (\\n    SELECT warehouse_id, event_time, cluster_count\\n    FROM system.compute.warehouse_events\\n    WHERE event_time >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) - INTERVAL 7 DAYS\\n      AND event_time < CURRENT_DATE() + INTERVAL 1 DAY\\n  ),\\n  events_with_next AS (\\n    SELECT warehouse_id, event_time, cluster_count,\\n      LEAD(event_time) OVER (PARTITION BY warehouse_id ORDER BY event_time) AS next_event_time\\n    FROM all_events\\n  ),\\n  running_windows AS (\\n    SELECT warehouse_id, event_time AS window_start,\\n      COALESCE(next_event_time, CURRENT_DATE() + INTERVAL 1 DAY) AS window_end\\n    FROM events_with_next\\n    WHERE cluster_count > 0\\n  ),\\n  daily_running AS (\\n    SELECT w.warehouse_id, d.usage_date,\\n      GREATEST(w.window_start, CAST(d.usage_date AS TIMESTAMP)) AS window_start,\\n      LEAST(w.window_end, CAST(d.usage_date AS TIMESTAMP) + INTERVAL 1 DAY) AS window_end\\n    FROM running_windows w\\n    JOIN date_spine d\\n      ON w.window_end > CAST(d.usage_date AS TIMESTAMP)\\n     AND w.window_start < CAST(d.usage_date AS TIMESTAMP) + INTERVAL 1 DAY\\n    WHERE GREATEST(w.window_start, CAST(d.usage_date AS TIMESTAMP))\\n        < LEAST(w.window_end, CAST(d.usage_date AS TIMESTAMP) + INTERVAL 1 DAY)\\n  ),\\n  warehouse_uptime AS (\\n    SELECT warehouse_id, usage_date,\\n      SUM((UNIX_TIMESTAMP(window_end) - UNIX_TIMESTAMP(window_start)) / 60.0) AS total_running_minutes\\n    FROM daily_running\\n    GROUP BY warehouse_id, usage_date\\n  ),\\n  billing_agg AS (\\n    SELECT\\n      u.usage_date,\\n      u.usage_metadata.warehouse_id AS warehouse_id,\\n      LEAST(\\n        SUM((UNIX_TIMESTAMP(LEAST(u.usage_end_time, CAST(u.usage_date AS TIMESTAMP) + INTERVAL 1 DAY))\\n             - UNIX_TIMESTAMP(GREATEST(u.usage_start_time, CAST(u.usage_date AS TIMESTAMP)))) / 60.0),\\n        1440.0\\n      ) AS billing_running_minutes,\\n      SUM(u.usage_quantity * COALESCE(p.pricing.default, 0)) AS total_spend\\n    FROM system.billing.usage u\\n    LEFT JOIN system.billing.list_prices p\\n      ON u.sku_name = p.sku_name AND u.cloud = p.cloud AND p.price_end_time IS NULL\\n    WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AND u.usage_date <= CURRENT_DATE()\\n      AND u.usage_metadata.warehouse_id IS NOT NULL\\n      AND u.usage_quantity > 0\\n    GROUP BY u.usage_date, u.usage_metadata.warehouse_id\\n  ),\\n  combined_uptime AS (\\n    SELECT\\n      COALESCE(e.warehouse_id, b.warehouse_id) AS warehouse_id,\\n      COALESCE(e.usage_date, b.usage_date) AS usage_date,\\n      COALESCE(e.total_running_minutes, b.billing_running_minutes) AS total_running_minutes,\\n      CASE WHEN e.warehouse_id IS NOT NULL THEN \'events\' ELSE \'billing\' END AS uptime_source\\n    FROM warehouse_uptime e\\n    FULL OUTER JOIN billing_agg b\\n      ON e.warehouse_id = b.warehouse_id AND e.usage_date = b.usage_date\\n  ),\\n  wh_info AS (\\n    SELECT warehouse_id, warehouse_name, warehouse_size, workspace_id, warehouse_type,\\n      COALESCE(auto_stop_minutes, 10) AS auto_stop_mins,\\n      COALESCE(max_clusters, 1) AS max_num_clusters\\n    FROM system.compute.warehouses\\n    QUALIFY ROW_NUMBER() OVER (PARTITION BY warehouse_id ORDER BY change_time DESC) = 1\\n  ),\\n  qw_raw AS (\\n    SELECT\\n      qh.compute.warehouse_id AS warehouse_id,\\n      DATE(GREATEST(qh.start_time, CAST(DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AS TIMESTAMP))) AS usage_date,\\n      GREATEST(qh.start_time, CAST(DATE(qh.start_time) AS TIMESTAMP)) AS w_start,\\n      LEAST(COALESCE(qh.end_time, CAST(DATE(qh.start_time) AS TIMESTAMP) + INTERVAL 1 DAY),\\n            CAST(DATE(qh.start_time) AS TIMESTAMP) + INTERVAL 1 DAY) AS w_end\\n    FROM system.query.history qh\\n    WHERE qh.start_time >= CAST(DATE_SUB(CURRENT_DATE(), {billing_lookback_days}) AS TIMESTAMP)\\n      AND qh.start_time < CURRENT_DATE() + INTERVAL 1 DAY\\n      AND qh.compute.warehouse_id IS NOT NULL\\n      AND COALESCE(qh.end_time, CURRENT_TIMESTAMP()) > CAST(DATE(qh.start_time) AS TIMESTAMP)\\n  ),\\n  qw_flagged AS (\\n    SELECT warehouse_id, usage_date, w_start, w_end,\\n      MAX(w_end) OVER (\\n        PARTITION BY warehouse_id, usage_date ORDER BY w_start\\n        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING\\n      ) AS prev_max_end\\n    FROM qw_raw\\n  ),\\n  qw_grouped AS (\\n    SELECT warehouse_id, usage_date, w_start, w_end,\\n      SUM(CASE WHEN prev_max_end IS NULL OR w_start > prev_max_end THEN 1 ELSE 0 END)\\n        OVER (PARTITION BY warehouse_id, usage_date ORDER BY w_start\\n              ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS grp\\n    FROM qw_flagged\\n  ),\\n  qw_merged AS (\\n    SELECT warehouse_id, usage_date, grp, MIN(w_start) AS grp_start, MAX(w_end) AS grp_end\\n    FROM qw_grouped\\n    GROUP BY warehouse_id, usage_date, grp\\n  ),\\n  busy_union AS (\\n    SELECT warehouse_id, usage_date,\\n      SUM(GREATEST((UNIX_TIMESTAMP(grp_end) - UNIX_TIMESTAMP(grp_start)) / 60.0, 0)) AS busy_union_minutes\\n    FROM qw_merged\\n    GROUP BY warehouse_id, usage_date\\n  ),\\n  qw_with_lag AS (\\n    SELECT qm.warehouse_id, qm.usage_date, qm.grp_start, qm.grp_end,\\n      LAG(qm.grp_end) OVER (PARTITION BY qm.warehouse_id, qm.usage_date ORDER BY qm.grp_start) AS prev_end,\\n      wh.auto_stop_mins\\n    FROM qw_merged qm\\n    JOIN wh_info wh ON qm.warehouse_id = wh.warehouse_id\\n  ),\\n  warm_hold AS (\\n    SELECT warehouse_id, usage_date,\\n      SUM(GREATEST(LEAST((UNIX_TIMESTAMP(grp_start) - UNIX_TIMESTAMP(prev_end)) / 60.0, auto_stop_mins * 1.0), 0)) AS warm_hold_minutes\\n    FROM qw_with_lag\\n    WHERE prev_end IS NOT NULL\\n    GROUP BY warehouse_id, usage_date\\n  )\\n  SELECT\\n    u.usage_date,\\n    u.warehouse_id,\\n    COALESCE(i.warehouse_name, u.warehouse_id) AS warehouse_name,\\n    COALESCE(i.warehouse_size, \'Unknown\') AS warehouse_size,\\n    CASE WHEN i.warehouse_type = \'SERVERLESS\' THEN \'SERVERLESS\' ELSE \'CLASSIC\' END AS warehouse_type,\\n    i.workspace_id,\\n    u.uptime_source,\\n    u.total_running_minutes,\\n    COALESCE(bu.busy_union_minutes, 0) AS busy_union_minutes,\\n    GREATEST(u.total_running_minutes - COALESCE(bu.busy_union_minutes, 0), 0) AS idle_minutes,\\n    COALESCE(wh.warm_hold_minutes, 0) AS warm_hold_minutes,\\n    COALESCE(i.auto_stop_mins, 10) AS auto_stop_mins,\\n    COALESCE(i.max_num_clusters, 1) AS max_num_clusters,\\n    COALESCE(c.total_spend, 0) AS total_spend,\\n    CASE\\n      WHEN COALESCE(i.warehouse_type, \'CLASSIC\') != \'SERVERLESS\'\\n        AND i.max_num_clusters <= 1\\n        AND u.uptime_source = \'events\'\\n        AND u.total_running_minutes > 0\\n      THEN COALESCE(c.total_spend, 0)\\n           * GREATEST(u.total_running_minutes - COALESCE(bu.busy_union_minutes, 0), 0)\\n           / u.total_running_minutes\\n      ELSE CAST(NULL AS DOUBLE)\\n    END AS estimated_idle_spend\\n  FROM combined_uptime u\\n  LEFT JOIN busy_union bu ON u.warehouse_id = bu.warehouse_id AND u.usage_date = bu.usage_date\\n  LEFT JOIN warm_hold wh ON u.warehouse_id = wh.warehouse_id AND u.usage_date = wh.usage_date\\n  JOIN wh_info i ON u.warehouse_id = i.warehouse_id\\n  LEFT JOIN billing_agg c ON u.warehouse_id = c.warehouse_id AND u.usage_date = c.usage_date\\n  WHERE u.total_running_minutes >= 1","daily_kpi_facts":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_kpi_facts` CLUSTER BY (usage_date, workspace_id) AS\\n\\n  SELECT\\n    u.usage_date,\\n    u.workspace_id,\\n    COUNT(DISTINCT CASE WHEN u.usage_metadata.job_id IS NOT NULL THEN CAST(u.usage_metadata.job_id AS STRING) END) AS distinct_jobs,\\n    SUM(CASE WHEN u.usage_metadata.job_id IS NOT NULL THEN 1 ELSE 0 END) AS job_run_rows,\\n    COUNT(DISTINCT CASE WHEN u.usage_metadata.job_id IS NOT NULL THEN u.identity_metadata.run_as END) AS distinct_job_owners,\\n    COUNT(DISTINCT CAST(u.usage_metadata.cluster_id AS STRING)) AS distinct_clusters,\\n    COUNT(DISTINCT CASE WHEN u.billing_origin_product = \'SQL\' THEN CAST(u.usage_metadata.warehouse_id AS STRING) END) AS distinct_sql_warehouses,\\n    SUM(CASE WHEN u.billing_origin_product = \'SQL\' THEN u.usage_quantity ELSE 0 END) AS sql_dbus,\\n    COUNT(DISTINCT CASE WHEN u.sku_name LIKE \'%INFERENCE%\' THEN u.usage_metadata.endpoint_name END) AS distinct_models,\\n    SUM(CASE WHEN u.sku_name LIKE \'%INFERENCE%\' THEN u.usage_quantity ELSE 0 END) AS serving_dbus\\n  FROM system.billing.usage u\\n  WHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n    AND u.usage_quantity > 0\\n  GROUP BY 1, 2","daily_lakeflow_stats":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_lakeflow_stats` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  DATE(period_start_time) AS usage_date,\\n  workspace_id,\\n  COUNT(*) AS total_runs,\\n  COUNT(CASE WHEN result_state = \'SUCCEEDED\' THEN 1 END) AS successful_runs,\\n  COALESCE(SUM((unix_timestamp(period_end_time) - unix_timestamp(period_start_time)) / 3600.0), 0) AS total_run_hours\\nFROM system.lakeflow.job_run_timeline\\nWHERE DATE(period_start_time) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND period_end_time IS NOT NULL\\nGROUP BY 1, 2","daily_query_users":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_query_users` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  DATE(start_time) AS usage_date,\\n  workspace_id,\\n  COALESCE(executed_by, CAST(executed_as_user_id AS STRING)) AS user_id\\nFROM system.query.history\\nWHERE DATE(start_time) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND (executed_by IS NOT NULL OR executed_as_user_id IS NOT NULL)\\nGROUP BY 1, 2, 3","daily_apps_identities":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_apps_identities` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  u.usage_date,\\n  u.workspace_id,\\n  COALESCE(u.usage_metadata.app_id, \'Unknown\') AS app_id,\\n  u.identity_metadata.run_as AS run_as\\nFROM system.billing.usage u\\nWHERE u.usage_date >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\n  AND u.usage_quantity > 0\\n  AND u.billing_origin_product = \'APPS\'\\n  AND u.identity_metadata.run_as IS NOT NULL\\nGROUP BY 1, 2, 3, 4","use_case_query_objects":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`use_case_query_objects` AS\\nSELECT CURRENT_DATE() AS snapshot_date, statement_id AS object_id,\\n  SUBSTRING(COALESCE(statement_text, CONCAT(\'Query \', statement_id)), 1, 100) AS object_name,\\n  workspace_id\\nFROM (\\n  SELECT statement_id, statement_text, workspace_id, start_time,\\n    ROW_NUMBER() OVER (ORDER BY start_time DESC) AS rn\\n  FROM system.query.history\\n  WHERE statement_id IS NOT NULL\\n    AND start_time >= DATE_SUB(CURRENT_DATE(), 30)\\n) t\\nWHERE rn <= 100","use_case_dashboard_objects":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`use_case_dashboard_objects` AS\\nSELECT CURRENT_DATE() AS snapshot_date, dashboard_id AS object_id, name AS object_name, workspace_id\\nFROM system.dashboards.dashboards\\nWHERE dashboard_id IS NOT NULL","daily_ai_gateway":"CREATE OR REPLACE TABLE `{catalog}`.`{schema}`.`daily_ai_gateway` CLUSTER BY (usage_date, workspace_id) AS\\nSELECT\\n  CAST(event_time AS DATE) AS usage_date,\\n  workspace_id,\\n  COALESCE(CAST(COALESCE(service_name, endpoint_name) AS STRING), \'__na__\') AS route_name,\\n  COALESCE(CAST(destination_model AS STRING), \'__na__\') AS model_name,\\n  COALESCE(CAST(requester AS STRING), \'(unknown)\') AS client_user,\\n  COUNT(*) AS request_count,\\n  SUM(CAST(COALESCE(input_tokens, 0) AS BIGINT)) AS input_tokens,\\n  SUM(CAST(COALESCE(output_tokens, 0) AS BIGINT)) AS output_tokens,\\n  SUM(CAST(COALESCE(total_tokens, COALESCE(input_tokens, 0) + COALESCE(output_tokens, 0)) AS BIGINT)) AS total_tokens,\\n  AVG(CAST(CAST(NULL AS DOUBLE) AS DOUBLE)) AS avg_latency_ms,\\n  SUM(CASE WHEN CAST(COALESCE(status_code, 0) AS INT) >= 400 THEN 1 ELSE 0 END) AS error_count,\\n  SUM(CASE WHEN CAST(COALESCE(status_code, 0) AS INT) < 400 THEN 1 ELSE 0 END) AS success_count\\nFROM {ai_gateway_table}\\nWHERE CAST(event_time AS DATE) >= DATE_SUB(CURRENT_DATE(), {billing_lookback_days})\\nGROUP BY 1, 2, 3, 4, 5"}')
missing_source_tables = {table for table, _ in missing_access}


def _is_optional_miss(table_name: str, message: str) -> bool:
    if table_name not in OPTIONAL_TABLES:
        return False
    lowered = message.lower()
    return (
        "table_or_view_not_found" in lowered
        or "cannot be found" in lowered
        or "table or view" in lowered
        or "sqlstate: 42p01" in lowered
    )


spark.sql(f"CREATE SCHEMA IF NOT EXISTS `{CATALOG}`.`{SCHEMA}`")

build_results = []
for table_name, template in TABLE_SQL.items():
    required_widget = OPTIONAL_WIDGETS.get(table_name)
    if required_widget and not required_widget[1]:
        build_results.append(
            (
                table_name,
                "SKIPPED_OPTIONAL",
                0,
                f"Widget {required_widget[0]} is empty; not building optional gold",
            )
        )
        continue
    blocked_by = sorted(
        missing_source_tables.intersection(TABLE_DEPENDENCIES[table_name])
    )
    if blocked_by:
        build_results.append(
            (
                table_name,
                "SKIPPED_PERMISSION",
                0,
                "Missing SELECT on " + ", ".join(blocked_by),
            )
        )
        continue
    print(f"Building {table_name} ...")
    try:
        spark.sql(
            template.format(
                catalog=CATALOG,
                schema=SCHEMA,
                billing_lookback_days=LOOKBACK_DAYS,
                ai_gateway_table=AI_GATEWAY_TABLE,
            )
        )
        row_count = spark.sql(
            f"SELECT COUNT(*) AS row_count FROM `{CATALOG}`.`{SCHEMA}`.`{table_name}`"
        ).first()["row_count"]
        build_results.append((table_name, "READY", int(row_count), None))
    except Exception as exc:
        if _is_optional_miss(table_name, str(exc)):
            build_results.append(
                (
                    table_name,
                    "SKIPPED_OPTIONAL",
                    0,
                    "Optional source is not connected",
                )
            )
        else:
            build_results.append((table_name, "FAILED", 0, str(exc)))

failed = [row for row in build_results if row[1] == "FAILED"]
skipped = [row for row in build_results if row[1] == "SKIPPED_PERMISSION"]
skipped_optional = [row for row in build_results if row[1] == "SKIPPED_OPTIONAL"]
display(
    spark.createDataFrame(
        build_results,
        "table_name STRING, status STRING, row_count LONG, error STRING",
    )
)
if failed:
    raise RuntimeError(
        "Gold table build failed: " + ", ".join(row[0] for row in failed)
    )
ready_names = set(row[0] for row in build_results if row[1] == "READY")
core_missing = [name for name in CORE_TABLES if name not in ready_names]
if core_missing:
    raise RuntimeError(
        "Required gold tables were not built: " + ", ".join(core_missing)
    )
if skipped:
    print(
        f"Skipped {len(skipped)} permission-dependent gold tables: "
        + ", ".join(row[0] for row in skipped)
    )
if skipped_optional:
    print(
        f"Skipped {len(skipped_optional)} optional gold tables: "
        + ", ".join(row[0] for row in skipped_optional)
    )

# COMMAND ----------

spark.sql(
    f"CREATE SHARE IF NOT EXISTS `{SHARE}` "
    "COMMENT 'Cost Observability warehouse gold tables'"
)

schema_fqn = f"{CATALOG}.{SCHEMA}"
ready_tables = [row[0] for row in build_results if row[1] == "READY"]

# Inventory the share so the run is idempotent and can reconcile an existing
# table-level share into a schema-level one (a schema object and a table object
# from the same schema cannot coexist).
current_objects = []
for row in spark.sql(f"SHOW ALL IN SHARE `{SHARE}`").collect():
    d = row.asDict()
    current_objects.append(
        (str(d.get("shared_object") or ""), str(d.get("type") or "").upper())
    )
schema_shared = any(
    obj.lower() == schema_fqn.lower() and typ == "SCHEMA"
    for obj, typ in current_objects
)

share_results = []

if SHARE_MODE == "schema":
    # A schema share covers every current AND future gold table in the schema, so
    # recipients keep working as new aggregates land without re-running share.
    # Never point this at a live app schema that also holds invoice actuals.
    existing_tables = [
        str(row["tableName"])
        for row in spark.sql(f"SHOW TABLES IN `{CATALOG}`.`{SCHEMA}`").collect()
    ]
    leaked_invoices = [name for name in INVOICE_GOLD if name in existing_tables]
    if leaked_invoices:
        raise RuntimeError(
            "Schema share would publish invoice gold tables: "
            + ", ".join(leaked_invoices)
            + ". Use share_mode=table, or choose a gold-only schema."
        )
    stale_tables = [
        obj for obj, typ in current_objects
        if typ == "TABLE" and obj.lower().startswith(schema_fqn.lower() + ".")
    ]
    if stale_tables and not schema_shared and ALLOW_SCHEMA_MIGRATION != "yes":
        raise RuntimeError(
            "This share already contains table-level objects. To avoid disrupting "
            "recipient access, the runbook will not replace them automatically. "
            "Keep share_mode=table, or first grant the recipient app service principal "
            "USE CATALOG, USE SCHEMA, and SELECT ON SCHEMA; then rerun with "
            "allow_schema_migration=yes."
        )
    for obj in stale_tables:
        cat, sch, tbl = obj.split(".", 2)
        spark.sql(f"ALTER SHARE `{SHARE}` REMOVE TABLE `{cat}`.`{sch}`.`{tbl}`")
        share_results.append((obj, "REMOVED (replaced by schema share)"))
    if schema_shared:
        share_results.append((schema_fqn, "SCHEMA ALREADY SHARED"))
    else:
        spark.sql(f"ALTER SHARE `{SHARE}` ADD SCHEMA `{CATALOG}`.`{SCHEMA}`")
        share_results.append((schema_fqn, "SCHEMA ADDED"))
else:
    if schema_shared:
        raise RuntimeError(
            f"Share `{SHARE}` already shares the whole schema {schema_fqn}. "
            "Use share_mode=schema, or manually REMOVE SCHEMA before using table mode."
        )
    existing = {obj.lower() for obj, _ in current_objects}
    for table_name in ready_tables:
        full_name = f"{CATALOG}.{SCHEMA}.{table_name}"
        if full_name.lower() not in existing:
            spark.sql(
                f"ALTER SHARE `{SHARE}` "
                f"ADD TABLE `{CATALOG}`.`{SCHEMA}`.`{table_name}`"
            )
            share_results.append((table_name, "ADDED"))
        else:
            share_results.append((table_name, "ALREADY SHARED"))

if RECIPIENT:
    spark.sql(f"GRANT SELECT ON SHARE `{SHARE}` TO RECIPIENT `{RECIPIENT}`")

display(
    spark.createDataFrame(
        share_results,
        "object STRING, share_status STRING",
    )
)

